insert into public.recovery_curriculum_outcomes (
  outcome_id, curriculum_id, schema_version, school_year_profile, competence_axis, cefr_target,
  label_it, observable_outcome_it, programme_requirement, blocking_candidate, status, source_payload, source_hash
)
select
  outcome_id, curriculum_id, schema_version, school_year_profile, competence_axis, cefr_target,
  label_it, observable_outcome_it, programme_requirement, blocking_candidate, status, source_payload, source_hash
from source
on conflict (outcome_id) do update set
  curriculum_id = excluded.curriculum_id,
  schema_version = excluded.schema_version,
  school_year_profile = excluded.school_year_profile,
  competence_axis = excluded.competence_axis,
  cefr_target = excluded.cefr_target,
  label_it = excluded.label_it,
  observable_outcome_it = excluded.observable_outcome_it,
  programme_requirement = excluded.programme_requirement,
  blocking_candidate = excluded.blocking_candidate,
  status = excluded.status,
  source_payload = excluded.source_payload,
  source_hash = excluded.source_hash,
  updated_at = now()
where public.recovery_curriculum_outcomes.source_hash is distinct from excluded.source_hash;

do $$
declare
  v_total integer;
  v_approved integer;
begin
  select count(*), count(*) filter (where status = 'approved')
    into v_total, v_approved
  from public.recovery_curriculum_outcomes
  where curriculum_id = 'recovery-years-1-3-v2';

  if v_total <> 63 or v_approved <> 63 then
    raise exception 'Recovery Curriculum v2 seed integrity failed: total %, approved %', v_total, v_approved;
  end if;
end;
$$;

notify pgrst, 'reload schema';
